export function createRequestHandler(store: BlobStore): http.RequestListener {
  return (req, res) => {
    route(store, req, res).catch((err: unknown) => {
      // The client went away before sending the whole body (put() has
      // already removed the partial upload): there is no one to answer.
      if (req.readableAborted) {
        res.destroy();
        return;
      }
      console.error("unhandled error while serving request:", err);
      if (!res.headersSent) {
        sendJson(res, 500, { error: "internal server error" });
      } else {
