import { createHash } from "node:crypto";
import { Readable, Transform } from "node:stream";

/** A failure to report to the user as is (no stack trace). */
export class ClientError extends Error {
  override name = "ClientError";
}

export interface RemoteBlob {
  key: string;
  size: number;
  sha256: string;
  modified_at: string;
}

/** URL of `/blobs/{key}`: each path segment percent-encoded, `/` kept. */
export function blobUrl(server: URL, key: string): URL {
  return new URL(`blobs/${key.split("/").map(encodeURIComponent).join("/")}`, server);
}

/** Thin wrapper over the server's HTTP API (see syncbox-openapi.yaml). */
export class SyncboxClient {
  constructor(private readonly server: URL) {}

  async list(): Promise<RemoteBlob[]> {
    const url = new URL("blobs", this.server);
    const res = await this.send(url, { method: "GET" }, "GET /blobs");
    if (res.status !== 200) {
      throw await unexpectedStatus("GET /blobs", res);
    }
    let body: unknown;
    try {
      body = await res.json();
    } catch {
      throw new ClientError(`GET /blobs: server returned a response that is not valid JSON`);
    }
    if (!Array.isArray(body) || !body.every(isRemoteBlob)) {
      throw new ClientError(`GET /blobs: server returned an unexpected response`);
    }
    return body;
  }

  /**
   * Uploads `body` under `key` and checks that the server stored exactly the
   * bytes that were sent. Returns their SHA-256.
   */
  async put(key: string, body: Readable): Promise<string> {
    const what = `PUT ${key}`;
    const hash = createHash("sha256");
    const hashing = new Transform({
      transform(chunk: Buffer, _encoding, callback) {
        hash.update(chunk);
        callback(null, chunk);
      },
    });
    body.on("error", (err) => hashing.destroy(err));
    const res = await this.send(
      blobUrl(this.server, key),
      {
        method: "PUT",
        headers: { "Content-Type": "application/octet-stream" },
        body: Readable.toWeb(body.pipe(hashing)) as ReadableStream<Uint8Array>,
        duplex: "half",
      },
      what,
    );
    if (res.status !== 201) {
      throw await unexpectedStatus(what, res);
    }
    let stored: unknown;
    try {
      stored = await res.json();
    } catch {
      throw new ClientError(`${what}: server returned a response that is not valid JSON`);
    }
    const sent = hash.digest("hex");
    if (typeof stored !== "object" || stored === null || (stored as { sha256?: unknown }).sha256 !== sent) {
      throw new ClientError(`${what}: server reports a different SHA-256 than the uploaded content has`);
    }
    return sent;
  }

  private async send(url: URL, init: RequestInit & { duplex?: "half" }, what: string): Promise<Response> {
    try {
      return await fetch(url, init);
    } catch (err) {
      throw new ClientError(`${what}: cannot reach server ${this.server.origin}: ${describeFetchError(err)}`);
    }
  }
}

function isRemoteBlob(value: unknown): value is RemoteBlob {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return typeof v.key === "string" && typeof v.size === "number" && typeof v.sha256 === "string";
}

async function unexpectedStatus(what: string, res: Response): Promise<ClientError> {
  let detail = "";
  try {
    const text = await res.text();
    try {
      const parsed = JSON.parse(text) as { error?: unknown };
      if (typeof parsed.error === "string") detail = `: ${parsed.error}`;
    } catch {
      // Not the server's JSON error format: leave it out.
    }
  } catch {
    // The status alone says enough.
  }
  return new ClientError(`${what}: server responded ${res.status} ${res.statusText}${detail}`);
}

/**
 * fetch() rejects with a generic "fetch failed" TypeError; the actual reason
 * (ECONNREFUSED, ENOTFOUND, a read error on the request body...) is in its
 * cause, possibly an AggregateError when several addresses were tried.
 */
function describeFetchError(err: unknown): string {
  let reason: unknown = err;
  while (reason instanceof Error && reason.cause !== undefined) {
    reason = reason.cause;
  }
  if (reason instanceof AggregateError && reason.errors.length > 0) {
    reason = reason.errors[0];
  }
  if (reason instanceof Error) {
    return reason.message || ((reason as NodeJS.ErrnoException).code ?? reason.name);
  }
  return String(reason);
}

